      ],
      "sibling_distinctions": [
        {
          "other_code": "N_3ebf96845f409274",
          "rule": "本节点关注衬底/外延层的宏观材料生长与制备；兄弟节点关注在已制备衬底上进行的热氧化膜生长及杂质扩散掺杂。"
        },
        {
          "other_code": "N_a01b9d775e5e1413",
          "rule": "本节点关注体材料（单晶/外延层）的生长；兄弟节点关注在衬底表面沉积特定功能的薄膜（如栅介质、金属层）。"
        }
      ],
      "cross_boundary_rule": "若内容涉及外延生长过程中的掺杂控制，归入本节点；若内容涉及外延层形成后的离子注入或热扩散激活，归入离子注入与热退火或热氧化与扩散掺杂。"
    },
    {
      "node_code": "N_3ebf96845f409274",
      "definition": "研究利用高温氧化形成二氧化硅绝缘层及通过热扩散引入杂质以改变半导体电学特性的工艺，涵盖氧化动力学、氧化膜质量及扩散分布控制。",
      "boundary": "聚焦于基于热力学和扩散机制的氧化与掺杂工艺。边界包括：1. 干氧/湿氧热氧化工艺及氧化膜特性；2. 磷、硼、砷等杂质的热扩散掺杂；3. 氧化与扩散对器件参数（如阈值电压、结深）的影响。若内容涉及离子注入或光刻图形化，则不在此列。",
