        "热氧化工艺（干氧、湿氧、快速热氧化）及氧化膜缺陷控制",
        "热扩散掺杂工艺（预沉积、驱入）及杂质分布模拟",
        "氧化层作为栅介质或隔离层的工艺应用"
      ],
      "excludes": [
        "离子注入掺杂工艺（归入离子注入与热退火工艺）",
        "光刻胶涂布或图形转移工艺（归入光刻技术与刻蚀工艺）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_6c62f9ff0e9c75f2",
          "rule": "本节点关注热扩散掺杂及氧化膜生长；兄弟节点关注高能离子注入掺杂及退火激活/修复工艺。"
        },
        {
          "other_code": "N_a01b9d775e5e1413",
          "rule": "本节点关注氧化硅膜及杂质扩散；兄弟节点关注多晶硅、金属、介质等薄膜的CVD/PVD沉积。"
        }
      ],
      "cross_boundary_rule": "若内容涉及氧化层作为掩蔽层在扩散过程中的作用，归入本节点；若内容涉及氧化层作为栅介质在先进节点中的高k材料替代，需结合薄膜沉积或先进结构节点判断。"
    },
    {
      "node_code": "N_e36bb7b5164731",
      "definition": "研究将掩模版图形精确转移到晶圆表面的光刻技术及去除非保护区域材料的刻蚀工艺，涵盖光刻胶化学、曝光系统、刻蚀机理及图形保真度控制。",
      "boundary": "聚焦于图形化制造的核心环节，包括光刻（从接触式到EUV）及刻蚀（干法/湿法）。边界包括：1. 光刻胶涂布、曝光、显影；2. 刻蚀选择比、各向异性控制；3. 图形转移精度与缺陷分析。若内容涉及薄膜沉积或掺杂，则不在此列。",
      "includes": [
        "光刻工艺（光刻胶、掩模版、曝光光源、对准技术）",
        "干法刻蚀（等离子体、RIE）与湿法刻蚀工艺",
        "图形转移过程中的侧壁修饰、抗反射涂层及缺陷控制"
      ],
      "excludes": [
        "薄膜沉积工艺（归入薄膜沉积技术）",
        "化学机械抛光（归入化学机械抛光）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_a01b9d775e5e1413",
          "rule": "本节点关注图形的转移与去除（定义形状）；兄弟节点关注材料的添加（形成层）。"
        },
        {
          "other_code": "N_96d62afb44695ff2",
          "rule": "本节点关注图形化刻蚀；兄弟节点关注平坦化抛光，两者常交替进行但功能不同。"
        }
      ],
      "cross_boundary_rule": "若内容涉及光刻胶在刻蚀过程中的抗刻蚀性能，归入本节点；若内容涉及刻蚀后表面粗糙度对后续沉积的影响，可关联薄膜沉积，但主挂载仍为刻蚀。"
    }
  ]
}
